package local.ondemand;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Remote-first filtered discovery. Filters and loaded posters survive title/Back navigation. */
final class DiscoverBrowser {
 final MainActivity a;String media,genre;int year;final List<JSONObject> results=new ArrayList<>();final Set<String> seen=new HashSet<>();final Map<String,Integer> offsets=new HashMap<>();final Set<String> finished=new HashSet<>();boolean busy;int revision;Button[] filters;View more;String pendingFocus="";
 DiscoverBrowser(MainActivity app){a=app;android.content.SharedPreferences p=a.getSharedPreferences("discover",0);media=p.getString("type","movie");genre=p.getString("genre","");year=p.getInt("year",0);a.current=this::show;show();}
 String label(){return media.equals("both")?"Movies & Series":media.equals("series")?"Series":"Movies";}
 void save(){a.getSharedPreferences("discover",0).edit().putString("type",media).putString("genre",genre).putInt("year",year).apply();}
 void change(String type,String g,int y){media=type;genre=g;year=y;save();results.clear();seen.clear();offsets.clear();finished.clear();revision++;busy=false;pendingFocus="";show();}
 void show(){a.screen("Discover","");busy=false;revision++;filters=new Button[]{a.button(label(),()->new AlertDialog.Builder(a).setTitle("Discover type").setSingleChoiceItems(new String[]{"Movies","Series","Movies & Series"},media.equals("movie")?0:media.equals("series")?1:2,(d,n)->{d.dismiss();change(new String[]{"movie","series","both"}[n],genre,year);}).setNegativeButton("Cancel",null).show()),a.button(genre.isEmpty()?"All genres":genre,this::chooseGenre),a.button(year==0?"Any year":String.valueOf(year),this::chooseYear),a.button("Reset",()->change("movie","",0))};LinearLayout bar=new LinearLayout(a);bar.setTag("discover:filters");for(int i=0;i<filters.length;i++){Button b=filters[i];b.setTag("discover:filter:"+i);b.setTextSize(12);b.setSingleLine(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,a.dp(34),i==3?.65f:1);p.setMargins(0,0,a.dp(7),a.dp(8));bar.addView(b,p);}a.page.addView(bar,2);draw();if(results.isEmpty()&&!done())load();}
 void chooseGenre(){int chosen=0;for(int i=1;i<DiscoverFilter.GENRES.length;i++)if(DiscoverFilter.GENRES[i].equals(genre))chosen=i;new AlertDialog.Builder(a).setTitle("Genre").setSingleChoiceItems(DiscoverFilter.GENRES,chosen,(d,n)->{d.dismiss();change(media,n==0?"":DiscoverFilter.GENRES[n],year);}).setNegativeButton("Cancel",null).show();}
 void chooseYear(){int now=Calendar.getInstance().get(Calendar.YEAR);String[] years=new String[now-1920+2];years[0]="Any year";for(int i=1;i<years.length;i++)years[i]=String.valueOf(now-i+1);int selected=year==0?0:now-year+1;new AlertDialog.Builder(a).setTitle("Release year · Series use first year").setSingleChoiceItems(years,Math.max(0,Math.min(years.length-1,selected)),(d,n)->{d.dismiss();change(media,genre,n==0?0:Integer.parseInt(years[n]));}).setNegativeButton("Cancel",null).show();}
 List<String> types(){return media.equals("both")?Arrays.asList("movie","series"):Collections.singletonList(media);}
 boolean done(){for(String t:types())if(!finished.contains(t)&&!(t.equals("series")&&year>0&&year<1960))return false;return true;}
 String summary(){return label()+" · "+(genre.isEmpty()?"All genres":genre)+" · "+(year==0?"Any year":year)+(!media.equals("movie")&&year>0?" (series first year)":"");}
 void draw(){String focus=!a.restoreFocus.isEmpty()?a.restoreFocus:!pendingFocus.isEmpty()?pendingFocus:a.getCurrentFocus()!=null?String.valueOf(a.getCurrentFocus().getTag()):"";a.rows.removeAllViews();List<View> cards=new ArrayList<>();int columns=PosterCard.columns(a);GridLayout grid=new GridLayout(a);grid.setColumnCount(columns);a.rows.addView(grid);for(JSONObject m:results){String t=m.optString("type","movie");View card=PosterCard.create(a,m,"discover:title:"+t+":"+m.optString("id"),()->{View chosen=a.page.findViewWithTag("discover:title:"+t+":"+m.optString("id"));if(chosen!=null)chosen.requestFocus();a.selected=m;a.type=t;a.go(a::detail);});GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=PosterCard.width(a);p.height=PosterCard.height(a);p.setMargins(0,0,a.dp(8),a.dp(8));grid.addView(card,p);cards.add(card);}if(results.isEmpty())a.rows.addView(a.text(busy?"Finding titles…":done()?"No matches found.":"No matches in the titles loaded. Load more to keep looking.",13));more=null;if(!done()&&results.size()<200){Button button=a.button(busy?"Loading…":"Load more titles",this::load);button.setTag("discover:more");button.setEnabled(!busy);button.setTextSize(12);a.rows.addView(button);more=button;}if(results.size()>=200)a.rows.addView(a.text("200 matches shown · Narrow the filters to explore further.",12));for(int i=0;i<filters.length;i++){final int index=i;filters[i].setOnKeyListener((v,k,e)->{View next=k==21?filters[Math.max(0,index-1)]:k==22?filters[Math.min(filters.length-1,index+1)]:k==20?cards.isEmpty()?more:cards.get(0):k==19?v:null;if(next==null)return k==20;if(e.getAction()==0)next.requestFocus();return true;});}for(int i=0;i<cards.size();i++){final int at=i;cards.get(i).setOnKeyListener((v,k,e)->{View next=k==21?cards.get(at%columns==0?at:at-1):k==22?cards.get(at%columns==columns-1?at:Math.min(at+1,cards.size()-1)):k==19?at<columns?filters[0]:cards.get(at-columns):k==20?at+columns<cards.size()?cards.get(at+columns):more!=null?more:v:null;if(next==null)return false;if(e.getAction()==0)next.requestFocus();return true;});}if(more!=null)more.setOnKeyListener((v,k,e)->{if(k!=19)return false;if(e.getAction()==0)(cards.isEmpty()?filters[0]:cards.get(cards.size()-1)).requestFocus();return true;});a.status.setText((busy?"Loading · ":"")+summary()+" · "+results.size()+" matches");View target=focus.isEmpty()?null:a.page.findViewWithTag(focus);if(target!=null&&target.isFocusable()&&target.isEnabled()){target.requestFocus();a.restoreFocus="";}else filters[0].requestFocus();pendingFocus="";}
 void load(){if(busy||done()||results.size()>=200)return;busy=true;final int token=a.generation,version=revision;final String g=genre;final int y=year;final List<String> kinds=new ArrayList<>(types());final Map<String,Integer> positions=new HashMap<>(offsets);final Set<String> completed=new HashSet<>(finished);final Api catalogApi=a.api;pendingFocus=a.getCurrentFocus()!=null?String.valueOf(a.getCurrentFocus().getTag()):"";draw();a.worker.submit(()->{List<JSONObject> added=new ArrayList<>();Set<String> ended=new HashSet<>();Map<String,Integer> advanced=new HashMap<>();String error="";for(String t:kinds){if(completed.contains(t)||t.equals("series")&&y>0&&y<1960)continue;try{int skip=positions.containsKey(t)?positions.get(t):0;JSONArray page=catalogApi.discoverPage(t,g,y,skip);int length=page==null?0:page.length();if(length==0)ended.add(t);advanced.put(t,skip+50);for(int i=0;i<length;i++){JSONObject original=page.optJSONObject(i);if(original==null||!DiscoverFilter.accepts(original,g,y))continue;JSONObject m=new JSONObject(original.toString());m.put("type",t);added.add(m);}}catch(Exception e){error="Some titles could not load · Retry Load more";}}final String note=error;a.clock.post(()->{if(token!=a.generation||version!=revision||a.isFinishing())return;busy=false;offsets.putAll(advanced);finished.addAll(ended);int previous=results.size();for(JSONObject m:added){String id=m.optString("type")+":"+m.optString("id");if(!m.optString("id").isEmpty()&&seen.add(id)&&results.size()<200)results.add(m);}if(previous>0&&results.size()>previous)pendingFocus="discover:title:"+results.get(previous).optString("type")+":"+results.get(previous).optString("id");draw();if(!note.isEmpty())a.status.setText(summary()+" · "+note);});});}
}
